    return stmt


def parse_script(tokens: list[Token]) -> list[Statement]:
    """Parse zero or more ';'-separated statements up to EOF.

    Empty statements (consecutive ';' or a trailing ';') are skipped; an
    empty token stream (just EOF) yields ``[]``.

    Raises:
        SQLSyntaxError: if any statement is malformed.
    """
    stmts = []
    while tokens and tokens[0].type != TokenType.EOF:
        try:
            stmt = parse(tokens)
            if stmt is not None:
                stmts.append(stmt)
        except SQLSyntaxError as e:
            raise SQLSyntaxError(f"Error parsing script: {e}")
        if tokens and tokens[0].value == ";":
            consume(TokenType.OPERATOR)  # ;
    return stmts


def parse_expression(tokens: list[Token]) -> Expr:
    """Parse a single WHERE-style expression that must consume every token
    up to EOF.

    Raises:
        SQLSyntaxError: if the tokens do not form exactly one expression.
    """
    def consume(expected_type: TokenType):
        token = tokens.pop(0)
        if token.type != expected_type:
            raise SQLSyntaxError(f"Expected {expected_type}, got {token.type}")
        return token

    def peek() -> Token:
        if not tokens:
            raise SQLSyntaxError("Unexpected EOF")
        return tokens[0]

    def accept(expected_type: TokenType) -> bool:
        if tokens and tokens[0].type == expected_type:
            tokens.pop(0)
            return True
        return False

    def parse_primary() -> Expr:
        token = consume(TokenType.ANY)
        if token.type == TokenType.INTEGER:
            return Literal(int(token.value))
        elif token.type == TokenType.STRING:
            return Literal(token.value)
        elif token.type == TokenType.KEYWORD:
            if token.value == "TRUE":
                return Literal(True)
            elif token.value == "FALSE":
                return Literal(False)
            elif token.value == "NULL":
                return Literal(None)
            else:
                return ColumnRef(token.value)
        elif token.type == TokenType.OPERATOR and token.value == "(":
            expr = parse_or_expr()
            consume(TokenType.OPERATOR)  # )
            return expr
        else:
            raise SQLSyntaxError(f"Unexpected token: {token.type}")

    def parse_predicate() -> Expr:
        expr = parse_primary()
        if accept(TokenType.KEYWORD) and peek().value == "IS":
            consume(TokenType.KEYWORD)  # IS
            if accept(TokenType.KEYWORD) and peek().value == "NOT":
                consume(TokenType.KEYWORD)  # NOT
                consume(TokenType.KEYWORD)  # NULL
                return IsNull(expr, True)
            consume(TokenType.KEYWORD)  # NULL
            return IsNull(expr, False)
        elif peek().type == TokenType.OPERATOR and peek().value in COMPARISON_OPS:
            op = consume(TokenType.OPERATOR).value
            right = parse_primary()
            return Comparison(op, expr, right)
        else:
            return expr

    def parse_not_expr() -> Expr:
        if accept(TokenType.KEYWORD) and peek().value == "NOT":
            consume(TokenType.KEYWORD)  # NOT
            operand = parse_not_expr()
            return Not(operand)
        return parse_predicate()

    def parse_and_expr() -> Expr:
        expr = parse_not_expr()
        while accept(TokenType.KEYWORD) and peek().value == "AND":
            consume(TokenType.KEYWORD)  # AND
            right = parse_not_expr()
            expr = And(expr, right)
        return expr

    def parse_or_expr() -> Expr:
        expr = parse_and_expr()
        while accept(TokenType.KEYWORD) and peek().value == "OR":
            consume(TokenType.KEYWORD)  # OR
            right = parse_and_expr()
            expr = Or(expr, right)
        return expr

    if not tokens or tokens[-1].type != TokenType.EOF:
        raise SQLSyntaxError("Expression must end with EOF")

    expr = parse_or_expr()
    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after expression")

    return expr
